using Game.SceneFlow;
namespace TrafficLightIntoKorea.Diagnostics {
internal static class DomTrace {
 private static object lastView;private static bool lastEnabled;private static bool installed;
 internal static void Tick(){try{var view=GameManager.instance?.userInterface?.view?.View;if(view==null)return;bool enabled=Probe.Session!=null;if(!object.ReferenceEquals(view,lastView)){lastView=view;installed=false;}if(!enabled&&!installed)return;if(!installed){view.ExecuteScript(Script);installed=true;lastEnabled=!enabled;}if(enabled!=lastEnabled){view.ExecuteScript("window.tlkDetailedTrace && window.tlkDetailedTrace.set("+(enabled?"true":"false")+");");lastEnabled=enabled;}}catch{Probe.RecordFailure();}}
 internal static void Dispose(){try{GameManager.instance?.userInterface?.view?.View?.ExecuteScript("window.tlkDetailedTrace && window.tlkDetailedTrace.dispose();");}catch{}installed=false;lastView=null;}
 // Capture at document level includes JS-only buttons. Pointer movement is sampled only inside TLIK's panel.
 private const string Script=@"(function(){if(window.tlkDetailedTrace)return;var enabled=false,lastMove=0,lastHover=null;var types=['click','contextmenu','change','input','keydown','mousedown','mouseup','mouseover','mousemove'];function record(e){if(!enabled)return;var t=e.target;if(!t||!t.closest)return;var panel=t.closest('.tlki-panel');var button=t.closest('button,[role=button],[role=tab],input,select,[role=checkbox]');if(!panel&&!button)return;if(!panel&&['click','contextmenu','change','keydown'].indexOf(e.type)<0)return;if(e.type==='keydown'&&e.key!=='Enter'&&e.key!==' '&&e.key!=='Escape')return;if(e.type==='mouseover'){if(lastHover===button)return;lastHover=button;}var now=Date.now();if(e.type==='mousemove'||e.type==='input'){if(now-lastMove<150)return;lastMove=now;}var target=button||t;try{engine.trigger('tlkIndividual.trace',JSON.stringify({event:e.type,panel:!!panel,tag:target.tagName,id:target.id,role:target.getAttribute('role'),label:(target.getAttribute('aria-label')||target.title||target.textContent||'').slice(0,100),value:panel&&('value'in target)?String(target.value).slice(0,100):null,x:e.clientX,y:e.clientY,key:e.key}));}catch(ex){}}types.forEach(function(type){document.addEventListener(type,record,true);});window.tlkDetailedTrace={set:function(value){enabled=value;},dispose:function(){types.forEach(function(type){document.removeEventListener(type,record,true);});delete window.tlkDetailedTrace;}};}());";
}
}
